/* 作者：@jiuyi0204。未经作者许可，禁止二次修改与二次上传。 */

/* ===== src/kernel/scrollbars.css ===== */
/* v7：只隐藏滚动条外观，保留滚轮、触摸、键盘、代码、表格与抽屉滚动。 */
:where(
    html,
    body,
    #sheld,
    #sheld *,
    #chat,
    .drawer-content,
    .popup-content,
    .scrollable,
    .select2-results__options,
    #send_textarea,
    #chat .mes_text pre,
    #chat .mes_text .table-responsive
) {
    scrollbar-width: none;
    -ms-overflow-style: none;
}

:where(
    html,
    body,
    #sheld,
    #sheld *,
    #chat,
    .drawer-content,
    .popup-content,
    .scrollable,
    .select2-results__options,
    #send_textarea,
    #chat .mes_text pre,
    #chat .mes_text .table-responsive
)::-webkit-scrollbar {
    width: 0;
    height: 0;
}

/* ===== src/tokens.css ===== */
/* 樱岚青笺 v7：批准色卡、字体与状态令牌 */
:root {
    --yl-paper: rgba(252, 253, 255, 0.94);
    --yl-blue-050: #f5f8fd;
    --yl-blue-100: #e6ebf6;
    --yl-blue-200: #d8e4f4;
    --yl-blue-400: #8b9bc1;
    --yl-blue-700: #35568a;
    --yl-blue-900: #173f79;
    --yl-pink-100: #f5e7e8;
    --yl-pink-300: #e3a3a4;
    --yl-ink: #173f79;
    --yl-muted: #7385ac;
    --yl-line: rgba(53, 86, 138, 0.24);
    --yl-font: "Source Han Serif SC", "Noto Serif SC", "Songti SC", "SimSun", serif;
    --theme-surface: var(--yl-blue-050);
    --theme-surface-muted: var(--yl-blue-100);
    --theme-surface-disabled: #edf1f7;
    --theme-text-primary: var(--yl-blue-900);
    --theme-text-secondary: var(--yl-muted);
    --theme-text-disabled: #687a9b;
    --theme-border: var(--yl-line);
    --theme-focus-ring: rgba(53, 86, 138, 0.72);
    --theme-opacity-disabled: 0.72;
    --theme-shadow: 0 10px 28px rgba(53, 86, 138, 0.12);
    --theme-code-inline-surface: rgba(225, 234, 247, 0.8);
    --theme-code-block-surface: rgba(238, 244, 252, 0.96);
    --theme-code-text: #24446f;
    --theme-code-muted: #687a9b;
    --theme-code-accent: #a45161;
    --theme-code-selection: rgba(216, 228, 244, 0.92);
    --theme-code-overflow: auto;
    --st-theme-mobile-reading-width: 36rem;
    --st-theme-mobile-reading-padding: 6px;
}

/* ===== src/chat-layout.css ===== */
/* 樱岚青笺 v7：主聊天结构与手机正文轴 */
#chat {
    box-sizing: border-box;
    padding: 18px 10px 12px 22px;
    scroll-padding-block: 18px 12px;
}

#chat .mes {
    box-sizing: border-box;
    margin-block: 0 12px;
    gap: 12px;
}

#chat .mesAvatarWrapper {
    flex: 0 0 72px;
    width: 72px;
    min-width: 72px;
}

#chat .mesAvatarWrapper .avatar {
    width: 56px;
    height: 56px;
    min-width: 56px;
    min-height: 56px;
    margin: 4px auto 0;
}

#form_sheld {
    box-sizing: border-box;
    padding: 0 18px 14px;
}

#send_form,
#nonQRFormItems,
#send_textarea {
    box-sizing: border-box;
}

#options_button,
#extensionsMenuButton,
#send_but,
#mes_stop {
    width: 42px;
    min-width: 42px;
    height: 42px;
    min-height: 42px;
}

@media (max-width: 700px) {
    #chat {
        padding: 10px 8px 8px;
    }

    #chat .mes[is_system="false"] {
        position: relative;
        display: flex;
        flex-direction: column;
        align-items: stretch;
        margin-bottom: 9px;
    }

    #chat .mes[is_system="false"] > .mesAvatarWrapper {
        position: absolute;
        top: 10px;
        left: 8px;
        width: 52px;
        min-width: 52px;
        padding-bottom: 0;
    }

    #chat .mes[is_system="false"] > .mesAvatarWrapper .avatar {
        width: 44px;
        height: 44px;
        min-width: 44px;
        min-height: 44px;
        margin: 0 auto;
    }

    #chat .mes[is_system="false"] > .mes_block {
        box-sizing: border-box;
        inline-size: 100%;
        min-inline-size: 0;
        padding-left: 0;
    }

    #chat .mes[is_system="false"] > .mes_block > .ch_name {
        box-sizing: border-box;
        min-height: 52px;
        padding-left: 60px;
    }

    #chat .mes[is_system="false"] > .mes_block > .mes_text {
        box-sizing: border-box;
        inline-size: min(100%, var(--st-theme-mobile-reading-width));
        max-inline-size: 100%;
        margin-inline: auto !important;
        padding-inline: var(--st-theme-mobile-reading-padding) !important;
    }

    #form_sheld {
        padding: 0 7px 8px;
    }

    #options_button,
    #extensionsMenuButton,
    #send_but,
    #mes_stop {
        width: 38px;
        min-width: 38px;
        height: 38px;
        min-height: 38px;
    }
}

/* ===== src/full-text.css ===== */
/* 樱岚青笺 v7：长正文与语义内容 */
#chat .mes_text {
    color: #28456f;
    font-family: var(--yl-font);
    font-size: 0.96875em;
    line-height: 1.72;
    letter-spacing: 0.012em;
    overflow-wrap: anywhere;
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
    color: var(--theme-text-primary);
    font-family: var(--yl-font);
    font-weight: 400;
}

#chat .mes_text :is(pre, table, img) {
    max-width: 100%;
}

#chat .mes_text img {
    height: auto;
}

#chat .mes_text pre,
#chat .mes_reasoning pre {
    color: var(--theme-code-text) !important;
    background-color: var(--theme-code-block-surface) !important;
    background-image: none !important;
    border: 1px solid rgba(53, 86, 138, 0.22) !important;
    border-radius: 8px;
    box-shadow: inset 0 1px 2px rgba(53, 86, 138, 0.05) !important;
    overflow-x: auto;
}

#chat .mes_text blockquote,
#chat .mes_reasoning blockquote {
    color: #28456f !important;
    margin: 0;
    padding: 8px 10px;
    background-color: var(--theme-code-block-surface) !important;
    background-image: none !important;
    border: 1px solid rgba(53, 86, 138, 0.2) !important;
    border-left: 3px solid rgba(190, 132, 143, 0.66) !important;
    border-radius: 0 8px 8px 0;
    box-shadow: none !important;
}

#chat .mes_text blockquote blockquote,
#chat .mes_reasoning blockquote blockquote {
    margin-top: 7px;
    background-color: rgba(223, 231, 244, 0.9) !important;
    border-color: rgba(53, 86, 138, 0.18) !important;
    border-left-color: rgba(53, 86, 138, 0.52) !important;
}

#chat .mes_text code,
#chat .mes_reasoning code {
    color: var(--theme-code-text);
    background-color: var(--theme-code-inline-surface);
    border: 1px solid rgba(53, 86, 138, 0.14);
    border-radius: 4px;
    text-shadow: none;
}

#chat .mes_text pre code,
#chat .mes_reasoning pre code,
#chat .mes_text pre code.hljs,
#chat .mes_reasoning pre code.hljs {
    color: var(--theme-code-text) !important;
    background-color: transparent !important;
    background-image: none !important;
    text-shadow: none;
}

#chat .mes_text :is(.hljs, .hljs-subst, .hljs-punctuation, .hljs-operator) {
    color: var(--theme-code-text) !important;
    opacity: 1;
    text-shadow: none;
}

#chat .mes_text :is(.hljs-comment, .hljs-quote, .hljs-meta) {
    color: var(--theme-code-muted) !important;
    opacity: 1;
    text-shadow: none;
}

#chat .mes_text :is(.hljs-keyword, .hljs-selector-tag, .hljs-title, .hljs-string, .hljs-number, .hljs-literal) {
    color: var(--theme-code-accent) !important;
    opacity: 1;
    text-shadow: none;
}

#chat .mes_text :is(code, pre)::selection,
#chat .mes_text :is(code, pre) *::selection {
    color: var(--theme-code-text);
    background-color: var(--theme-code-selection);
}

@media (max-width: 700px) {
    #chat .mes_text {
        font-size: 0.875em;
        line-height: 1.64;
    }
}

/* ===== src/visual.css ===== */
/* 樱岚青笺：色彩、字体与纸面 */
@font-face {
    font-family: "Source Han Serif SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/sourcehanserifsc/sourcehanserifsc.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

body {
    color: var(--yl-ink);
    background-color: #dfe8f6;
    background-image:
        linear-gradient(rgba(242, 247, 255, 0.48), rgba(250, 247, 250, 0.58)),
        url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/a76f4d9bfcfb919d2ecf932022a61cd41d9cb75f/assets/%E6%A8%B1%E5%B2%9A%E9%9D%92%E7%AC%BA/background-cherry-blossom.webp");
    background-position: center;
    background-size: cover;
    font-family: var(--yl-font);
}

#sheld {
    background: var(--yl-paper);
    border-inline: 1px solid rgba(53, 86, 138, 0.28);
    box-shadow: 0 14px 40px rgba(32, 66, 116, 0.16);
}

#chat {
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(245, 248, 253, 0.68));
}

#form_sheld {
    background: linear-gradient(180deg, rgba(248, 251, 255, 0.72), rgba(255, 255, 255, 0.94));
}

:is(#chat, #form_sheld, #top-settings-holder, #left-nav-panel, #rm_api_block, #AdvancedFormatting, #openai_api-presets, #completion_prompt_manager, #user-settings-block, #WorldInfo, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup, #dialogue_popup, #options, #extensionsMenu, .select2-container, #toast-container) :is(button:not(.fa-solid):not(.fa-regular):not(.fa-brands):not(.fas):not(.far):not(.fab), input, select, textarea) {
    font-family: var(--yl-font);
}

/* ===== src/windows/top-bar.css ===== */
/* 樱岚青笺：顶栏九个原生入口（W02） */
:root {
    --yl-topbar-height: 68px;
    --topBarBlockSize: var(--yl-topbar-height) !important;
}

#top-settings-holder {
    box-sizing: border-box;
    height: var(--yl-topbar-height);
    padding: 6px 8px 7px;
    gap: 4px;
    color: var(--yl-blue-700);
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(237, 243, 251, 0.94));
    border: 1px solid rgba(53, 86, 138, 0.28);
    border-top: 0;
    border-radius: 0 0 16px 16px;
    box-shadow: 0 7px 18px rgba(53, 86, 138, 0.11);
}

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > [class~="drawer-toggle"] {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    min-width: 0;
    gap: 4px;
    padding: 4px 2px 3px;
    color: var(--yl-blue-700);
    background: rgba(255, 255, 255, 0.28);
    border: 1px solid transparent;
    border-radius: 10px;
    transition:
        color 120ms ease,
        background-color 120ms ease,
        border-color 120ms ease;
}

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > [class~="drawer-toggle"] > [class~="drawer-icon"] {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: auto;
    min-width: 26px;
    height: 24px;
    padding: 0;
    color: currentColor;
    font-size: 21px;
    line-height: 1;
    opacity: 0.8;
    text-shadow: none;
    transition: color 120ms ease, opacity 120ms ease;
}

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > [class~="drawer-toggle"]::after {
    color: var(--yl-blue-700);
    font-family: var(--yl-font);
    font-size: 10.5px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.02em;
    white-space: nowrap;
    pointer-events: none;
}

#ai-config-button > .drawer-toggle::after { content: "参数"; }
#sys-settings-button > .drawer-toggle::after { content: "连接"; }
#advanced-formatting-button > .drawer-toggle::after { content: "回复"; }
#WI-SP-button > .drawer-toggle::after { content: "世界书"; }
#user-settings-button > .drawer-toggle::after { content: "设置"; }
#backgrounds-button > .drawer-toggle::after { content: "背景"; }
#extensions-settings-button > .drawer-toggle::after { content: "扩展"; }
#persona-management-button > .drawer-toggle::after { content: "人设"; }
#rightNavHolder > .drawer-toggle::after { content: "角色"; }

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > [class~="drawer-toggle"]:hover {
    color: var(--yl-blue-900);
    background: rgba(216, 228, 244, 0.72);
    border-color: rgba(53, 86, 138, 0.26);
}

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > [class~="drawer-toggle"] > [class~="drawer-icon"].openIcon {
    color: #8d5363;
    opacity: 1;
}

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > [class~="drawer-toggle"]:hover > [class~="drawer-icon"],
#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > [class~="drawer-toggle"] > [class~="drawer-icon"]:focus-visible {
    opacity: 1;
}

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > [class~="drawer-toggle"] > [class~="drawer-icon"]:focus-visible {
    outline: 2px solid rgba(53, 86, 138, 0.72);
    outline-offset: 3px;
    border-radius: 5px;
}

#top-settings-holder #API-status-top.redOverlayGlow {
    color: #b55f70;
    text-shadow: 0 0 8px rgba(227, 163, 164, 0.48);
}

@media (max-width: 700px) {
    :root {
        --yl-topbar-height: 60px;
    }

    #top-settings-holder {
        padding: 5px 3px 6px;
        gap: 1px;
        border-radius: 0 0 13px 13px;
    }

    #top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > [class~="drawer-toggle"] {
        gap: 3px;
        padding: 3px 1px 2px;
        border-radius: 8px;
    }

    #top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > [class~="drawer-toggle"] > [class~="drawer-icon"] {
        min-width: 22px;
        height: 21px;
        font-size: 18px;
    }

    #top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > [class~="drawer-toggle"]::after {
        font-size: 9px;
        letter-spacing: 0;
    }
}

/* ===== src/windows/main-chat.css ===== */
/* 樱岚青笺：主聊天最小切片 */
#chat .mes[is_user="true"],
#chat .mes[is_user="false"][is_system="false"] {
    color: var(--yl-ink);
    border: 1px solid var(--yl-line);
    border-radius: 14px;
    padding: 13px 14px 12px 12px;
    box-shadow: none;
}

#chat .mes[is_user="true"] {
    background-color: rgba(250, 242, 244, 0.96);
    background-image: none;
    border-color: rgba(190, 132, 143, 0.25);
}

#chat .mes[is_user="false"][is_system="false"] {
    background-color: rgba(238, 244, 252, 0.97);
    background-image: none;
    border-color: rgba(53, 86, 138, 0.22);
}

/* 删除消息模式：使用官方真实复选框与脚本写入的 .selected 状态 */
#chat .mes > input[type="checkbox"].del_checkbox {
    box-sizing: border-box;
    width: 24px;
    min-width: 24px;
    height: 24px;
    min-height: 24px;
    margin: 12px 2px 0 0;
    align-self: flex-start;
    color: #173f79;
    background-color: rgba(255, 255, 255, 0.98);
    background-image: none;
    border: 2px solid rgba(53, 86, 138, 0.72);
    border-radius: 7px;
    outline: 0;
    box-shadow: none;
    filter: none;
    opacity: 1;
}

#chat .mes > input[type="checkbox"].del_checkbox:checked {
    --SmartThemeCheckboxTickColor: #ffffff;
    color: #ffffff;
    background-color: #35568a;
    border-color: #234978;
    outline: 2px solid rgba(139, 155, 193, 0.42);
    outline-offset: 2px;
}

#chat .mes > input[type="checkbox"].del_checkbox:focus-visible {
    outline: 3px solid rgba(227, 159, 159, 0.58);
    outline-offset: 2px;
}

#chat .mes.selected {
    color: var(--yl-ink);
    background-color: rgba(229, 237, 249, 0.99);
    border-color: rgba(53, 86, 138, 0.72);
    border-inline-start: 5px solid #35568a;
    outline: 2px solid rgba(53, 86, 138, 0.42);
    outline-offset: -2px;
}

#chat .mes.selected[is_user="true"] {
    background-color: rgba(247, 224, 228, 0.99);
    border-color: rgba(164, 81, 97, 0.7);
    border-inline-start-color: #a45161;
    outline-color: rgba(190, 132, 143, 0.48);
}

#chat .mes.selected[is_user="false"][is_system="false"] {
    background-color: rgba(218, 230, 247, 0.99);
    border-color: rgba(53, 86, 138, 0.72);
    border-inline-start-color: #35568a;
    outline-color: rgba(53, 86, 138, 0.42);
}

/* 删除确认栏：保留官方显隐与确认/取消逻辑，只补足真实按钮的可见状态 */
#form_sheld #dialogue_del_mes {
    box-sizing: border-box;
    color: #173f79;
    background: rgba(247, 250, 255, 0.98);
    border: 1px solid rgba(53, 86, 138, 0.3);
    border-radius: 13px;
    padding: 8px 10px;
    box-shadow: 0 7px 20px rgba(53, 86, 138, 0.12);
}

#form_sheld #dialogue_del_mes .menu_button {
    box-sizing: border-box;
    min-width: 7.5em;
    margin-inline: 8px;
    padding: 8px 18px;
    color: #173f79;
    background-color: #e8eff9;
    border: 1px solid rgba(53, 86, 138, 0.38);
    border-radius: 9px;
    filter: none;
    opacity: 1;
}

#form_sheld #dialogue_del_mes #dialogue_del_mes_ok {
    color: #ffffff;
    background-color: #a45161;
    border-color: #8d4554;
}

#form_sheld #dialogue_del_mes #dialogue_del_mes_cancel {
    color: #173f79;
    background-color: #e8eff9;
    border-color: rgba(53, 86, 138, 0.38);
}

#form_sheld #dialogue_del_mes #dialogue_del_mes_ok:hover,
#form_sheld #dialogue_del_mes #dialogue_del_mes_cancel:hover {
    filter: brightness(0.97);
    box-shadow: 0 0 0 3px rgba(139, 155, 193, 0.2);
}

#form_sheld #dialogue_del_mes #dialogue_del_mes_ok:focus-visible,
#form_sheld #dialogue_del_mes #dialogue_del_mes_cancel:focus-visible {
    outline: 3px solid rgba(227, 159, 159, 0.58);
    outline-offset: 2px;
}

#chat .mesAvatarWrapper .avatar {
    position: relative;
    border: 1px solid rgba(53, 86, 138, 0.34);
    border-radius: 50%;
    background-color: rgba(255, 255, 255, 0.92);
    box-shadow: none;
}

#chat .mesAvatarWrapper .avatar > img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    border-radius: 50%;
}

#chat .mesAvatarWrapper .avatar::after {
    content: "";
    position: absolute;
    inset: -10px;
    pointer-events: none;
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
}

#chat .mes[is_user="true"] .avatar::after {
    background-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/a76f4d9bfcfb919d2ecf932022a61cd41d9cb75f/assets/%E6%A8%B1%E5%B2%9A%E9%9D%92%E7%AC%BA/avatar-user.png");
    background-position: 50.3% 51.5%;
}

#chat .mes[is_user="false"] .avatar::after {
