/* ===== src/visual-states.css ===== */
/* 樱岚青笺 v7：关键组件完整视觉状态。选择器来自 1.14.0 官方节点或运行时状态。 */

/* reasoning_block/container.normal */
#chat .mes_reasoning_details {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* reasoning_block/container.collapsed */
#chat .mes_reasoning_details:not([open]) {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-muted);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* reasoning_block/container.expanded */
#chat .mes_reasoning_details[open] {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* reasoning_block/container.loading */
#chat .mes_reasoning_details[data-state="thinking"] {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-muted);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* reasoning_block/container.complete */
#chat .mes_reasoning_details:not([data-state="thinking"]) {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* reasoning_block/container.focus */
#chat .mes_reasoning_summary:focus-visible {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
    outline: 2px solid var(--theme-focus-ring);
    outline-color: var(--theme-focus-ring);
}

/* reasoning_block/text.normal */
#chat .mes_reasoning {
    color: var(--theme-text-primary);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* reasoning_block/icon.normal */
#chat .mes_reasoning_arrow {
    color: var(--theme-text-primary);
    opacity: 1;
    filter: none;
    text-shadow: none;
    box-shadow: none;
}

/* prompt_manager/entry.normal */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* prompt_manager/entry.disabled */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    color: var(--theme-text-disabled);
    background-color: var(--theme-surface-disabled);
    border: 1px solid var(--theme-border);
    opacity: var(--theme-opacity-disabled);
    filter: none;
    text-shadow: none;
}

/* prompt_manager/entry.selected */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:focus-within {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-muted);
    border: 1px solid var(--theme-focus-ring);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* prompt_manager/entry.unselected */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled):not(:focus-within) {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* prompt_manager/entry.hover */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-muted);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
