/* detached_overlays/item.hover */
.popup .list-group-item:hover {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-muted);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* detached_overlays/item.selected */
.popup .list-group-item.active {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-muted);
    border: 1px solid var(--theme-focus-ring);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* detached_overlays/item.disabled */
.popup .list-group-item.disabled {
    color: var(--theme-text-disabled);
    background-color: var(--theme-surface-disabled);
    border: 1px solid var(--theme-border);
    opacity: var(--theme-opacity-disabled);
    filter: none;
    text-shadow: none;
}

/* detached_overlays/item.focus */
.popup .list-group-item:focus-visible {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-muted);
    border: 1px solid var(--theme-focus-ring);
    opacity: 1;
    filter: none;
    text-shadow: none;
    outline: 2px solid var(--theme-focus-ring);
    outline-color: var(--theme-focus-ring);
}

/* detached_overlays/text.normal */
.popup .popup-content {
    color: var(--theme-text-primary);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

/* detached_overlays/icon.normal */
.popup .menu_button {
    color: var(--theme-text-primary);
    opacity: 1;
    filter: none;
    text-shadow: none;
    box-shadow: none;
}

/* ===== src/fallback.css ===== */
/* 资源失败时仍保持可读、可点。图片层从不遮断原交互节点。 */
#chat .mes[is_user="true"] .avatar {
    outline: 2px solid rgba(190, 132, 143, 0.5);
    outline-offset: 2px;
}

#chat .mes[is_user="false"] .avatar {
    outline: 2px solid rgba(53, 86, 138, 0.58);
    outline-offset: 2px;
}

#options_button,
#extensionsMenuButton,
#send_but,
#mes_stop {
    font-family: "Font Awesome 6 Free", "Font Awesome 5 Free", sans-serif;
}
